from copy import deepcopy


class Outcome:
    def __init__(self, ok=False, value=None, error=None):
        self.ok = ok
        self.value = value
        self.error = error


class DocumentActivator:
    def __init__(self, documents=None):
        source = {} if documents is None else dict(documents)
        self._documents = deepcopy(source)
        self.recent = []

    def exists(self, name):
        return isinstance(name, str) and name in self._documents

    def load(self, outcome, name):
        if not self.exists(name):
            outcome.ok, outcome.value, outcome.error = False, None, "document not found"
        elif self._documents[name].get("broken"):
            outcome.ok, outcome.value, outcome.error = False, None, "document cannot be loaded"
        else:
            outcome.ok = True
            outcome.value = deepcopy(self._documents[name])
            outcome.error = None
        return outcome

    def initialize(self, outcome, document):
        sections = document.get("sections")
        valid = (isinstance(sections, list) and bool(sections)
                 and all(isinstance(section, str) for section in sections))
        if not valid:
            outcome.ok, outcome.value, outcome.error = False, None, "invalid sections"
        else:
            outcome.ok, outcome.value, outcome.error = True, deepcopy(document), None
        return outcome

    def activate(self, name, remember=True):
        outcome = self.load(Outcome(), name)
        if not outcome.ok:
            return outcome
        outcome = self.initialize(outcome, outcome.value)
        if outcome.ok and remember and name not in self.recent:
            self.recent.append(name)
        return outcome
